// Schema and origin validation. Nothing reaches the model until this passes.
//
// Two request shapes are accepted:
//   { version: 1, mode: 'health' }            -> liveness probe
//   { version: 1, question, locale, grounding } -> inference
//
// Anything else is rejected here, cheaply, before Ollama is touched.
const PROTOCOL = 1;
const maxQuestion = Number($env.AJOOP_AI_MAX_QUESTION_CHARS || 500);
const allowed = String($env.AJOOP_AI_ALLOWED_ORIGINS || '')
  .split(',')
  .map((value) => value.trim())
  .filter(Boolean);

const headers = $json.headers || {};
const origin = headers.origin || headers.Origin || '';
const body = $json.body || {};

const reject = (error) => [{ json: { valid: false, error } }];

// An empty allowlist is a misconfiguration, not permission for everyone.
if (!allowed.length) return reject('bridge not configured');
if (!origin || !allowed.includes(origin)) return reject('origin not allowed');
if (body.version !== PROTOCOL) return reject('unsupported version');

if (body.mode === 'health') {
  return [{ json: { valid: true, health: true } }];
}

const question = typeof body.question === 'string' ? body.question.trim() : '';
if (!question) return reject('question required');
if (question.length > maxQuestion) return reject('question too long');

const grounding = body.grounding && typeof body.grounding === 'object' ? body.grounding : {};
const evidence = Array.isArray(grounding.evidence) ? grounding.evidence.slice(0, 3) : [];
const comparison = grounding.comparison && typeof grounding.comparison === 'object' ? grounding.comparison : null;

// No evidence means nothing to ground on. Say so rather than letting the model
// answer from its own memory, which is exactly the failure mode this bridge exists to prevent.
if (!evidence.length && !comparison) return reject('no grounding supplied');

const locales = ['en', 'tr', 'de', 'es', 'fr'];
const locale = locales.includes(body.locale) ? body.locale : 'en';
const depths = ['quick', 'normal', 'deep'];
const depth = depths.includes(body.depth) ? body.depth : 'normal';

return [{ json: { valid: true, health: false, question, locale, depth, evidence, comparison } }];

// Grounded prompt construction.
//
// THE EVIDENCE IS THE SOURCE OF TRUTH, NOT THE MODEL. The system message states
// that in the strongest terms available, and the user message carries only the
// canonical fields the browser sent. The model's job is reasoning and phrasing;
// it is explicitly forbidden from supplying portfolio facts of its own.
const data = $json;

const depthGuidance = {
  quick: 'Answer in one or two short sentences.',
  normal: 'Answer in two to four sentences, suitable for a recruiter skimming the page.',
  deep: 'Answer in one short paragraph, using more of the supplied proof points.',
}[data.depth];

// Deliberately terse. qwen3 is a reasoning model: in live testing every extra
// prohibition measurably lengthened its internal deliberation until it
// exhausted the token budget and returned nothing at all. This wording
// converged 3/3 while still refusing to invent facts. Keep it short.
const system = [
  "You describe Kaan Balci's portfolio using ONLY the evidence given.",
  'Never add facts, numbers, dates, employers, repositories or links that are not in the evidence.',
  'If the evidence lacks the answer, say the portfolio data does not contain it.',
  'Do not rank projects against each other.',
  'Answer in this language: ' + data.locale + '. ' + depthGuidance + ' Plain prose, no markdown.',
].join('\n');

const lines = [];
for (const item of data.evidence || []) {
  lines.push('PROJECT: ' + item.title);
  if (item.summary) lines.push('SUMMARY: ' + item.summary);
  if (Array.isArray(item.meta) && item.meta.length) lines.push('CONTEXT: ' + item.meta.join(' | '));
  if (Array.isArray(item.tags) && item.tags.length) lines.push('TECHNOLOGIES: ' + item.tags.join(', '));
  if (Array.isArray(item.proof) && item.proof.length) lines.push('PROOF POINTS: ' + item.proof.join(' | '));
  if (Array.isArray(item.sources) && item.sources.length) lines.push('AVAILABLE SOURCES: ' + item.sources.map((s) => s.kind).join(', '));
  lines.push('');
}
if (data.comparison) {
  lines.push('COMPARISON BETWEEN: ' + data.comparison.left + ' AND ' + data.comparison.right);
  for (const row of data.comparison.rows || []) {
    const format = (value) => (Array.isArray(value) ? value.join(', ') : value || 'not listed');
    lines.push(row.key + ' -> ' + data.comparison.left + ': ' + format(row.a) + ' // ' + data.comparison.right + ': ' + format(row.b));
  }
  lines.push('');
}

const user = [
  'PORTFOLIO EVIDENCE:',
  lines.join('\n').trim(),
  '',
  'VISITOR QUESTION:',
  data.question,
].join('\n');

return [{ json: { system, user, locale: data.locale } }];

// Output validation. A reachable model is not a trusted one.
//
// The model is asked for PLAIN PROSE, so its answer is read straight from
// message.content. An earlier revision ran JSON.parse(content) and took an
// .answer field from it; because nothing ever asked the model for JSON that
// parse always threw, raw became '', and every reply -- including correct ones
// -- was discarded as 'empty model response', so the AI path could never
// succeed. Keep this reader aligned with what the prompt actually requests.
const response = $json || {};
// think:true puts reasoning in message.thinking, which is deliberately ignored.
const raw = (response.message && response.message.content) || '';
const model = response.model || $env.AJOOP_AI_MODEL || 'qwen3:4b';

// Defence in depth: strip tagged reasoning or markup before it is ever shown.
const cleaned = String(raw)
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/<[^>]+>/g, '')
  .trim();

if (!cleaned) {
  return [{ json: { ok: false, error: 'empty model response' } }];
}
if (cleaned.length > 4000) {
  return [{ json: { ok: false, error: 'model response too long' } }];
}

return [{ json: { ok: true, mode: 'ai', answer: cleaned, model } }];

// Liveness requires both Ollama and the configured model; a running n8n alone
// must never make the browser claim AI Enhanced. No execution detail is exposed.
const model = $env.AJOOP_AI_MODEL || 'qwen3:4b';
const models = Array.isArray($json.models) ? $json.models : [];
const available = models.some((item) => item && (item.name === model || item.model === model));
return [{ json: available
  ? { ok: true, mode: 'health', model }
  : { ok: false, error: 'model unavailable' } }];

// Rejections carry a short reason and nothing else: no stack traces, no node
// names, no environment detail. The browser only needs to know it must fall back.
return [{ json: { ok: false, error: String($json.error || 'invalid request').slice(0, 120) } }];
